-- ONE-TIME TEST DATA (extra): a fifth showcase survey using every newer question type.
-- Run AFTER ops/seed_test_data.sql (it needs the Globex demo customer). Same rules: it runs
-- as a temporary member seed-bot@example.test, is labelled TEST, and is removed by
-- ops/remove_test_data.sql. Generated by a script.
begin;

do $guard$
begin
  if not exists (select 1 from public.organizations where slug = 'globex-demo-test') then
    raise exception 'Run ops/seed_test_data.sql first (the Globex demo customer is missing).';
  end if;
  if exists (select 1 from public.surveys where slug = 'test-all-question-types') then
    raise exception 'The showcase survey already exists.';
  end if;
end $guard$;

insert into public.survey_members (email, organization_id, role, is_active, can_view_identity)
values ('seed-bot@example.test', null, 'owner', true, false);
select set_config('request.jwt.claims', '{"email":"seed-bot@example.test","role":"authenticated"}', true);

insert into public.surveys (slug, title, definition, table_name, published, organization_id, current_version, privacy_mode, category, purpose, created_by)
select 'test-all-question-types', 'Every Question Type (TEST)', '{"slug":"test-all-question-types","title":"Every Question Type (TEST)","brand":"Globex Demo Ltd","hiddenFields":["source"],"welcome":{"heading":"Question type showcase","body":["This is TEST data. It uses every question type, dynamic options, skip logic and hidden fields."],"startLabel":"Begin Survey"},"thankYou":{"heading":"Thank you","body":"Thanks, {{answer:who|friend}}!"},"sections":[{"id":"s1","title":"About you","questions":[{"id":"intro","type":"heading","label":"Let us start with you","hint":"Your name and contact details are only used to follow up on this survey."},{"id":"who","type":"fullname","label":"Your name","required":true},{"id":"phone","type":"phone","label":"Phone number","placeholder":"+91 …"},{"id":"address","type":"multitext","label":"Postal address","rows":["Street","City","PIN code"],"columnPrefix":"address"}]},{"id":"s2","title":"Your choices","questions":[{"id":"used","type":"checkbox","label":"Which channels do you use?","required":true,"options":["Email","Chat","Phone","In person"]},{"id":"fav","type":"radio","label":"Which one is your favourite?","required":true,"options":["(none)","(none 2)"],"optionsFrom":{"questionId":"used","mode":"selected"}},{"id":"region","type":"radio","label":"Which region are you in?","required":true,"options":["North","South"]},{"id":"store","type":"select","label":"Which store do you visit?","required":true,"options":["Delhi","Chennai","Online"],"placeholder":"Choose a store","optionLogic":{"Delhi":{"questionId":"region","equals":["North"]},"Chennai":{"questionId":"region","equals":["South"]}}},{"id":"colour","type":"image","label":"Which colour do you prefer?","options":["Blue","Green","Orange"],"images":["https://placehold.co/400x300/2961B6/ffffff?text=Blue","https://placehold.co/400x300/2E8B57/ffffff?text=Green","https://placehold.co/400x300/E07B00/ffffff?text=Orange"]}]},{"id":"s3","title":"Details","questions":[{"id":"budget","type":"sum","label":"Split 100 points across what matters most to you","required":true,"rows":["Price","Quality","Speed"],"total":100,"columnPrefix":"budget","unit":"pts"},{"id":"doc","type":"file","label":"Upload a supporting document (optional)","maxSizeMb":5,"accept":"any"},{"id":"sign","type":"signature","label":"Sign to confirm your answers","required":true}]}]}'::jsonb, 'survey_test_all_question_types', true, o.id, 1,
       'ANONYMOUS'::survey_privacy_mode, 'Other', 'Test data: showcase of every newer question type, dynamic options and hidden fields.', 'seed-bot@example.test'
from public.organizations o where o.slug = 'globex-demo-test';
insert into public.survey_versions (survey_id, version_number, definition, created_by)
select id, 1, definition, 'seed-bot@example.test' from public.surveys where slug = 'test-all-question-types';
select public.ensure_survey_response_table((select id from public.surveys where slug = 'test-all-question-types'), null);

insert into public.audit_logs (organization_id, user_email, action_type, details)
values (null, 'seed-bot@example.test', 'TEST_DATA_SEEDED', jsonb_build_object('surveys', 1, 'note', 'Showcase survey; see ops/seed_test_data_extra.sql'));
delete from public.survey_members where lower(email) = 'seed-bot@example.test';

commit;
